 create(){if(this.failed)return;scene=this;const echoAtlas=this.textures.get('forest-echo'),echoSource=echoAtlas.getSourceImage();echoAtlas.add('idle',0,88,16,490,627);this.layer=this.add.container(0,0);const t=this.textures.get('traveler'),src=t.getSourceImage();for(let y=0;y<4;y++)for(let x=0;x<4;x++)t.add(y*4+x,0,Math.round(x*src.width/4),Math.round(y*src.height/4),Math.round(src.width/4),Math.round(src.height/4));for(let y=0;y<4;y++)this.anims.create({key:'walk'+y,frames:[0,1,2,3].map(x=>({key:'traveler',frame:y*4+x})),frameRate:7,repeat:-1});const vt=this.textures.get('traveler-vigilia'),vs=vt.getSourceImage();for(let i=0;i<16;i++)vt.add(i,0,(i%4)*vs.width/4,Math.floor(i/4)*vs.height/4,vs.width/4,vs.height/4);this.bg=this.add.image(0,0,state.place).setOrigin(0).setDisplaySize(1536,1024);const atlas=this.textures.get('residents'),atlasImage=atlas.getSourceImage();for(let i=0;i<4;i++)atlas.add(i,0,(i%2)*atlasImage.width/2,Math.floor(i/2)*atlasImage.height/2,atlasImage.width/2,atlasImage.height/2);this.npcs=[];this.hero=this.add.sprite(0,0,'traveler',8).setOrigin(.5,.96).setDisplaySize(88,88);const et=this.textures.get('elara-walk'),es=et.getSourceImage();for(let i=0;i<16;i++)et.add(i,0,(i%4)*es.width/4,Math.floor(i/4)*es.height/4,es.width/4,es.height/4);this.ally=this.add.sprite(0,0,'elara-walk',1).setOrigin(.5,.98).setDisplaySize(93,93);this.labels=[];this.cameras.main.setBounds(0,0,1536,1024);this.cameras.main.startFollow(this.hero,true,.12,.12);this.scale.on('resize',()=>this.resize());this.resize();ready=true;this.enter();$('loading').hidden=true;
 if(state.combat){try{if(!Array.isArray(state.combat.units)||!Array.isArray(state.combat.order)||!state.combat.units.some(u=>u.id==='hero'))throw Error();battle=new R.Battle(state.combat.kind,heroProfile,state);if(!battle.actor)throw Error();$('battle').hidden=false;document.body.classList.add('fighting');renderBattle();autoAt=performance.now()+2800;}catch{state.combat=null;battle=null;save();}}
 if(!state.flags.intro&&!battle){state.flags.intro=true;save();say('Valdara abre sus puertas','El centinela reconoce tu nombre. En la plaza, una boticaria discute con un escriba. La cera de tu carta sigue caliente. Acércate a Maela con el joystick o las flechas.',[['Explorar la plaza',()=>{}],['Revisar mi personaje',sheet]]);}}
